-- v266: the fertilisers of Quality (the farm's Quality, piece 3).
-- Run after v265 and with the matching site code. Safe to run twice.
--
-- A plant has two slots (lib/town/fertilisers): a base, put on in its first round and covering to its first picking,
-- and a top, put on while it grows and covering for its hours; a packet fills one bar whole or two by half, and the
-- best source of a bar counts, as for every other source. The two three-day packets (mist, night) also raise the floor
-- while they last. Twenty-five are made by hand from every line's things (the catalog's makes row); the leaf mulch is
-- the design's base leaf fertiliser and is no longer a growth feed (the catalog's farming row: tools), mineral water
-- its top. Putting one on is the farm deed "fert" (one from the bag, a stamina), done in v262's tend wrapper as
-- compost and the brush are; v259's covers read the two slots, and the settle counts a packet's narrowing.
begin;
set local statement_timeout='30s';
set local lock_timeout='5s';
do $$ begin
 if to_regprocedure('town.house_do(text,jsonb,jsonb,text,text,bigint)') is null then raise exception 'Run v265 before v266'; end if;
-- <guards:v266>
 if md5(replace(pg_get_functiondef('town.quality_covers(jsonb,bigint,bigint)'::regprocedure),chr(13),'')) not in ('fce9c3c2b13b04ed63500c2834453eb9','99a528365afdba72d208c7d468b85cfc') then raise exception 'Definition changed: town.quality_covers(jsonb,bigint,bigint); rebuild v266'; end if;
 if md5(replace(pg_get_functiondef('town.quality_accrue(jsonb,bigint,jsonb)'::regprocedure),chr(13),'')) not in ('55a5514c3c13471cc0fd1a8c8b0b6a5a','0177163c18e1c7c8ae9ec03f6753d90f') then raise exception 'Definition changed: town.quality_accrue(jsonb,bigint,jsonb); rebuild v266'; end if;
 if md5(replace(pg_get_functiondef('town.quality_care(text,jsonb,jsonb,text,jsonb,text,bigint)'::regprocedure),chr(13),'')) not in ('056461427f231ba5f1f2d5d7bec3002a','87c361cf9ae14f419305b00e9c57f91f') then raise exception 'Definition changed: town.quality_care(text,jsonb,jsonb,text,jsonb,text,bigint); rebuild v266'; end if;
 if md5(replace(pg_get_functiondef('town.deed_for(text,jsonb,text,text,bigint,text)'::regprocedure),chr(13),'')) not in ('9f7b4d2f441089a10cda0dc529187bdc','19ca8ee059e9d896379d03a20435162b') then raise exception 'Definition changed: town.deed_for(text,jsonb,text,text,bigint,text); rebuild v266'; end if;
 if md5(replace(pg_get_functiondef('town.tend(text,jsonb,jsonb,integer,integer,jsonb,text,bigint,boolean)'::regprocedure),chr(13),'')) not in ('2d1a8af13baf561f6e0a1fbb530b67ce','4135b7b90bf34996830ca9b2b4137722') then raise exception 'Definition changed: town.tend(text,jsonb,jsonb,integer,integer,jsonb,text,bigint,boolean); rebuild v266'; end if;
-- </guards:v266>
end $$;

