create or replace function town.quality_covers(p_plant jsonb, p_from bigint, p_to bigint)
returns table(role text, lvl double precision, c_from bigint, c_to bigint) language sql stable set search_path='' as $$
 with h as (select (town.cat('quality')->'hand'->>'level')::double precision lv, (town.cat('quality')->'hand'->>'water')::bigint wa,
                   (town.cat('quality')->'hand'->>'afterRain')::bigint ar, 9007199254740991::bigint e)
 select 'water', h.lv, (p_plant->>'watered')::bigint, (p_plant->>'watered')::bigint+h.wa from h where coalesce((p_plant->>'watered')::bigint,0)>0
 union all select 'water', h.lv, (p_plant->>'sown')::bigint, h.e from h where p_plant->'moist'='true'::jsonb
 union all select 'water', h.lv, r.r_from, r.r_to+h.ar from h, town.quality_rains(p_from-h.ar,p_to) r
 union all select 'water', h.lv, (p_plant->'localRain'->>'from')::bigint, (p_plant->'localRain'->>'until')::bigint+h.ar from h where jsonb_typeof(p_plant->'localRain')='object'
 union all select 'water', h.lv, p_from, (p_plant->>'wetUntil')::bigint from h where jsonb_typeof(p_plant->'wetUntil')='number'
 union all select 'soil', h.lv, (p_plant->>'compost')::bigint, h.e from h where jsonb_typeof(p_plant->'compost')='number'
 union all select 'pollen', h.lv, (p_plant->>'brushed')::bigint, h.e from h where jsonb_typeof(p_plant->'brushed')='number' and (p_plant->>'brushed')::bigint>=town.quality_round_start(p_plant)
 union all select 'pollen', h.lv, p_from, (p_plant->>'pollenUntil')::bigint from h where jsonb_typeof(p_plant->'pollenUntil')='number'
 union all select 'guard', h.lv, p_from, (p_plant->>'guard')::bigint from h where coalesce((p_plant->>'guard')::bigint,0)>0
 -- v266: its fertilisers (lib/town/fertilisers): a base to the first picking, a top for its hours
 union all select f.key, (f.value#>>'{}')::double precision, (p_plant->'base'->>'at')::bigint, h.e
   from h, jsonb_each(coalesce(town.cat('quality')->'ferts'->(p_plant->'base'->>'item')->'bars','{}'::jsonb)) f
   where jsonb_typeof(p_plant->'base')='object' and coalesce((p_plant->>'picked')::integer,0)=0
 union all select f.key, (f.value#>>'{}')::double precision, (p_plant->'top'->>'at')::bigint, coalesce((p_plant->'top'->>'until')::bigint,(p_plant->'top'->>'at')::bigint)
   from h, jsonb_each(coalesce(town.cat('quality')->'ferts'->(p_plant->'top'->>'item')->'bars','{}'::jsonb)) f
   where jsonb_typeof(p_plant->'top')='object'
$$;

create or replace function town.quality_accrue(p_q jsonb, p_to bigint, p_plant jsonb)
returns jsonb language plpgsql stable set search_path='' as $$
declare
 at_ bigint:=(p_q->>'at')::bigint; span_ double precision:=(p_q->>'span')::double precision; gift jsonb:=p_q->'bed';
 area double precision[]:=array[(p_q->'area'->>0)::double precision,(p_q->'area'->>1)::double precision,(p_q->'area'->>2)::double precision,(p_q->'area'->>3)::double precision];
 nar double precision[]:=array[coalesce((p_q->'nar'->>0)::double precision,0),coalesce((p_q->'nar'->>1)::double precision,0),coalesce((p_q->'nar'->>2)::double precision,0)];
 roles text[]:=array['soil','water','pollen','guard']; covs jsonb; cuts bigint[]; prog double precision[]; i integer; k integer;
 mid double precision; grew double precision; best double precision; lost double precision; hl double precision:=(town.cat('quality')->'house'->>'level')::double precision;
begin
 if p_to<=at_ then return p_q; end if;
 select coalesce(jsonb_agg(jsonb_build_array(c.role,c.lvl,c.c_from,c.c_to)),'[]'::jsonb) into covs from town.quality_covers(p_plant,at_,p_to) c;
 if jsonb_typeof(gift->'c')='object' then
  select covs || coalesce(jsonb_agg(jsonb_build_array(e.key,(e.value#>>'{}')::double precision,0,9007199254740991::bigint)),'[]'::jsonb) into covs from jsonb_each(gift->'c') e;
 end if;
 if jsonb_typeof(gift->'h')='array' then
  select covs || coalesce(jsonb_agg(jsonb_build_array(e->>'r',hl*(e->>'s')::double precision,(e->>'from')::bigint,(e->>'to')::bigint)),'[]'::jsonb) into covs from jsonb_array_elements(gift->'h') e;
 end if;
 select array_agg(t order by t) into cuts from (
  select at_ t union select p_to union select (e->>2)::bigint from jsonb_array_elements(covs) e union select (e->>3)::bigint from jsonb_array_elements(covs) e
 ) x where t>=at_ and t<=p_to;
 select array_agg(town.quality_progress(p_plant,t) order by n) into prog from unnest(cuts) with ordinality u(t,n);
 for i in 1..array_length(cuts,1)-1 loop
  grew:=greatest(0::double precision,prog[i+1]-prog[i]);
  continue when grew=0;
  span_:=span_+grew; mid:=(cuts[i]::double precision+cuts[i+1]::double precision)/2;
  for k in 1..4 loop
   select coalesce(max((e->>1)::double precision),0) into best from jsonb_array_elements(covs) e
    where e->>0=roles[k] and (e->>2)::double precision<=mid and mid<(e->>3)::double precision;
   lost:=case when k=1 then coalesce((gift->>'f')::double precision,0) else 0 end;
   area[k]:=area[k]+(least(1::double precision,best)-lost/(town.cat('quality')->>'bar')::double precision)*grew;
  end loop;
  if (gift->>'p')::integer=1 then nar[1]:=nar[1]+grew; end if;
  if jsonb_typeof(gift->'h')='array' then
   select coalesce(max((e->>'s')::double precision),0) into best from jsonb_array_elements(gift->'h') e
    where (e->>'x')::integer=1 and (e->>'from')::double precision<=mid and mid<(e->>'to')::double precision;
   nar[2]:=nar[2]+least(1::double precision,best)*grew;
  end if;
  -- v266: a three-day packet on it raises the floor while it lasts (lib/town/quality-plant's fertNarrows)
  if jsonb_typeof(p_plant->'top')='object' and town.cat('quality')->'ferts'->(p_plant->'top'->>'item')->>'narrows'='true'
     and (p_plant->'top'->>'at')::double precision<=mid and mid<coalesce((p_plant->'top'->>'until')::double precision,0) then nar[3]:=nar[3]+grew; end if;
 end loop;
 return p_q || jsonb_build_object('at',p_to,'span',span_,'area',to_jsonb(area),'nar',to_jsonb(nar));
end $$;

create or replace function town.quality_care(p_deed text, p_plot jsonb, p_bed jsonb, p_owner text, p_purse jsonb, p_me text, p_now bigint)
returns jsonb language plpgsql stable set search_path='' as $$
declare p jsonb:=coalesce(p_plot->'plant','null'::jsonb); purse_ jsonb; bed_ jsonb:=p_bed; hand_ text; f jsonb;
begin
 if p='null'::jsonb then return town.no('soil'); end if;
 -- v266: a fertiliser of Quality (lib/town/farm's care, "fert"): one from the bag, a stamina; the base, or the top for its hours
 if p_deed='fert' then
  hand_:=town.hand_of(p_purse); f:=town.cat('quality')->'ferts'->hand_;
  if hand_ is null or f is null then return town.no('hand'); end if;
  purse_:=town.spend(p_purse,(town.cat('quality')->'hand'->'costs'->>'fert')::double precision,p_now);
  purse_:=purse_ || jsonb_build_object('bag',town.take(purse_->'bag',hand_,1));
  if bed_ is not null and p_owner=p_me then bed_:=bed_ || jsonb_build_object('tended',p_now,'empty',0); end if;
  return jsonb_build_object('ok',true,'deed',p_deed,'purse',purse_,
   'plot',p_plot || jsonb_build_object('plant',p || case when f->>'slot'='base' then jsonb_build_object('base',jsonb_build_object('item',hand_,'at',p_now))
     else jsonb_build_object('top',jsonb_build_object('item',hand_,'at',p_now,'until',p_now+((f->>'hours')::double precision*3600000)::bigint)) end),
   'bed',coalesce(bed_,'null'::jsonb),'got','[]'::jsonb);
 end if;
 if p_deed='compost' and town.held(p_purse->'bag','compost')<1 then return town.no('none'); end if;
 purse_:=town.spend(p_purse,(town.cat('quality')->'hand'->'costs'->>p_deed)::double precision,p_now);
 if p_deed='compost' then purse_:=purse_ || jsonb_build_object('bag',town.take(purse_->'bag','compost',1)); end if;
 -- (the bed of its owner who tends it is tended now, and has a plant in it)
 if bed_ is not null and p_owner=p_me then bed_:=bed_ || jsonb_build_object('tended',p_now,'empty',0); end if;
 return jsonb_build_object('ok',true,'deed',p_deed,'purse',purse_,
  'plot',p_plot || jsonb_build_object('plant',p || jsonb_build_object(case when p_deed='compost' then 'compost' else 'brushed' end,p_now)),
  'bed',coalesce(bed_,'null'::jsonb),'got','[]'::jsonb);
end $$;

CREATE OR REPLACE FUNCTION town.deed_for(p_key text, p_plot jsonb, p_hand text, p_me text, p_now bigint, p_owner text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  seen jsonb := town.see(p_key, p_plot, p_now);
  kind text := coalesce(town.tool_of(p_hand), '');
  p jsonb := coalesce(p_plot->'plant', 'null'::jsonb);
  mine boolean := p_owner is null or p_owner = p_me;
  dead boolean := (seen->>'dead')::boolean;
  ripe boolean := (seen->>'ripe')::boolean;
begin
  if p->>'root' is not null and p->>'root' <> p_key then return null; end if;
  if kind = 'hoe' then
    return case when p <> 'null'::jsonb then case when not mine then null when dead then 'pull' else 'uproot' end
                when p_plot->>'soil' = 'wild' then 'clear' when p_plot->>'soil' = 'cleared' then 'till' end;
  end if;
  if kind = 'seed' then return case when mine and p_plot->>'soil' = 'tilled' and p = 'null'::jsonb then 'sow' end; end if;
  if p <> 'null'::jsonb and not dead then
    -- ── v262: the farm's own care, on one's own plant in one's own bed: compost once a planting, the brush once a round before it is ripe ──
    if p_hand = 'compost' and mine and p->>'by' = p_me and jsonb_typeof(p->'compost') is distinct from 'number' then return 'compost'; end if;
    if p_hand = 'pollenBrush' and mine and p->>'by' = p_me and not ripe
       and not coalesce(jsonb_typeof(p->'brushed') = 'number' and (p->>'brushed')::bigint >= town.quality_round_start(p), false) then return 'brush'; end if;
    -- ── v266: a fertiliser of Quality on one's own growing plant: a base in its first round, once; a top over no live top ──
    if town.cat('quality')->'ferts' ? coalesce(p_hand, '') and mine and p->>'by' = p_me and not ripe
       and (case when town.cat('quality')->'ferts'->p_hand->>'slot' = 'base'
                then coalesce((p->>'picked')::integer, 0) = 0 and jsonb_typeof(p->'base') is distinct from 'object'
                else not coalesce(jsonb_typeof(p->'top') = 'object' and coalesce((p->'top'->>'until')::bigint, 0) > p_now, false) end) then return 'fert'; end if;
    if kind = 'cure' and (seen->>'pest')::boolean then return 'cure'; end if;
    if kind = 'can' and not (seen->>'wet')::boolean and not (town.growing(p, p_now)->>'spent')::boolean
       and not (ripe and town.cat('crops')->(p->>'crop')->>'again' is null) then return 'water'; end if;
    if kind = 'feed' and (p->>'fed')::bigint = 0 then return 'feed'; end if;
    if kind = 'guard' and (p->>'guard')::bigint <= p_now
       and (not (seen->>'pest')::boolean or town.cat('farming')->'rids'->>p_hand is not null) then return 'feed'; end if;
    if ripe and mine then return 'pick'; end if;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION town.tend(p_key text, p_plot jsonb, p_bed jsonb, p_others integer, p_holds integer, p_purse jsonb, p_me text, p_now bigint, p_sure boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare did jsonb;bond_ jsonb;bed_ jsonb:=case when p_bed is null or p_bed='null'::jsonb then null else p_bed end;owner_ text;deed_ text;begin
 -- ── v262: the farm's own care (compost, the pollen brush) is done here, before the older chain ──
 owner_:=town.owner_of(bed_,p_others>0 or coalesce(p_plot->'plant','null'::jsonb)<>'null'::jsonb,p_now);
 deed_:=town.deed_for(p_key,p_plot,town.hand_of(p_purse),p_me,p_now,owner_);
 if deed_ in ('compost','brush','fert') then return town.quality_care(deed_,p_plot,bed_,owner_,p_purse,p_me,p_now); end if;
 did:=town.tend_v205(p_key,p_plot,p_bed,p_others,p_holds,p_purse,p_me,p_now,p_sure);
 if did->'ok'='true'::jsonb and did->>'deed' in ('clear','till','water') then did:=jsonb_set(did,'{purse}',town.train_element(p_purse,did->'purse',town.hand_stack(p_purse)));end if;
 if did->'ok'='true'::jsonb and did->>'deed'='sow' then bond_:=town.combo_seed(did->'purse',did->'plot',p_key,p_now);did:=did||bond_;end if;return did;end;
$function$;

-- (the functions written over keep the grants they had)

commit;
notify pgrst, 'reload schema';

-- What it should say afterwards:
--   select town.cat('quality')->'ferts'->'slatePowder'->>'slot', town.cat('makes') ? 'packetMist', town.cat('farming')->'tools' ? 'mulch';  -- base, true, false
